import numpy as np

# Parameters
N = 45  # Cube size
K = 89  # Number of colors expected
target_colors = set(range(K))

# Color function (assuming 0-based indexing: x, y, z in [0, N-1])
def color_func(x, y, z, K):
    return (x + y + z) % K

print(f"--- Verification for C(x, y, z) = (x+y+z) mod {K} with N={N} ---")

# 1. Check Z-layers (Fixed z)
all_z_layers_ok = True
for z in range(N):
    colors_in_layer = set()
    for x in range(N):
        for y in range(N):
            colors_in_layer.add(color_func(x, y, z, K))

    if colors_in_layer != target_colors:
        all_z_layers_ok = False
        print(f"FAIL: Z-layer at z={z} contains colors: {sorted(list(colors_in_layer))}")
        break

if all_z_layers_ok:
    print("SUCCESS: All Z-layers contain the full set of 89 colors.")

# 2. Check X-slices (Fixed x)
all_x_slices_ok = True
for x in range(N):
    colors_in_slice = set()
    for y in range(N):
        for z in range(N):
            colors_in_slice.add(color_func(x, y, z, K))

    if colors_in_slice != target_colors:
        all_x_slices_ok = False
        print(f"FAIL: X-slice at x={x} contains colors: {sorted(list(colors_in_slice))}")
        break

if all_x_slices_ok:
    print("SUCCESS: All X-slices contain the full set of 89 colors.")

# 3. Check Y-strips (Fixed y)
all_y_strips_ok = True
for y in range(N):
    colors_in_strip = set()
    for x in range(N):
        for z in range(N):
            colors_in_strip.add(color_func(x, y, z, K))

    if colors_in_strip != target_colors:
        all_y_strips_ok = False
        print(f"FAIL: Y-strip at y={y} contains colors: {sorted(list(colors_in_strip))}")
        break

if all_y_strips_ok:
    print("SUCCESS: All Y-strips contain the full set of 89 colors.")
